(()=>{"use strict";const e=window.BarfordMemberFlow;if(!e)return;function p(r,i){const s=e.money(e.eventPrice(r,i)),n=e.dialog("Event checkout",`<p class="payment-demo-badge">DEMO \xB7 No money will be taken</p><div class="payment-demo-summary"><span>${e.esc(r.name)}<small>${e.esc(e.priceLabel(i))}</small></span><strong>${e.esc(s)}</strong></div><div data-demo-stage></div>`);n.classList.add("payment-demo");const o=n.querySelector("[data-demo-stage]");let c,d=!1,l=!1,t="Apple Pay";n.addEventListener("close",()=>{d=!0,clearTimeout(c)},{once:!0});function m(){l=!1,o.innerHTML=`<p class="payment-demo-label">Choose how to pay</p><div class="payment-demo-methods" role="group" aria-label="Demo payment method">${["Apple Pay","Google Pay","Card"].map(a=>`<button type="button" data-demo-method="${a}" aria-pressed="${a===t}">${a}</button>`).join("")}</div><div class="payment-demo-card"><small>EXAMPLE PAYMENT CARD</small><strong>\u2022\u2022\u2022\u2022 \u2022\u2022\u2022\u2022 \u2022\u2022\u2022\u2022 4242</strong><span>Demo card \xB7 No card details needed</span></div><p data-demo-method-note>${t==="Card"?"This preview uses a sample card. The live checkout will let you enter your card details.":`A preview of paying with ${t}. Your wallet will not open.`}</p><button type="button" class="button payment-demo-pay" data-demo-confirm>Demo pay ${e.esc(s)}</button><p class="payment-demo-footnote">Presentation preview only. Your actual booking remains unpaid.</p>`,o.querySelectorAll("[data-demo-method]").forEach(a=>a.onclick=()=>{t=a.dataset.demoMethod,m(),o.querySelector(`[data-demo-method="${t}"]`).focus()}),o.querySelector("[data-demo-confirm]").onclick=()=>{l||d||(l=!0,o.innerHTML=`<div class="payment-demo-outcome" role="status" aria-live="polite"><span class="payment-demo-spinner" aria-hidden="true"></span><h3>Processing demo payment\u2026</h3><p>${e.esc(t)} \xB7 ${e.esc(s)}</p></div>`,c=setTimeout(()=>{d||!n.isConnected||(o.innerHTML=`<div class="payment-demo-outcome" role="status" aria-live="polite"><span class="payment-demo-tick" aria-hidden="true">\u2713</span><h3>Demo payment complete</h3><p><strong>${e.esc(s)}</strong> via ${e.esc(t)}</p><p>This is how confirmation will appear after a successful payment.</p><p class="payment-demo-footnote">No money was taken. Your actual booking remains unpaid.</p></div><button type="button" class="button payment-demo-pay" data-demo-done>Done</button><button type="button" class="button button-outline full-button" data-demo-replay>Replay demo</button>`,o.querySelector("[data-demo-done]").onclick=()=>n.close(),o.querySelector("[data-demo-replay]").onclick=m,o.querySelector("[data-demo-done]").focus())},1100))}}m()}window.BarfordPaymentDemo={open:p}})();
